INSERT INTO `revenues` (`id`, `school_id`, `fiscal_year_id`, `category`, `item_name`, `rate_per_head`, `eligible_count`, `calculated_amount`, `is_custom_rate`, `note`) VALUES
(1, 1, 1, 'subsidy', '1. เงินอุดหนุนรายหัว (การจัดการศึกษาขั้นพื้นฐาน)', 1980.00, 312, 617760.00, 0, 'เฉลี่ยรวม อ.1-3 (1,800 บ.) และ ป.1-6 (2,050 บ.)'),
(2, 1, 1, 'subsidy', '2. เงินอุดหนุนรายหัวส่วนเพิ่ม (Top Up) โรงเรียนคุณภาพประจำตำบล', 500.00, 312, 156000.00, 0, 'สนับสนุนพัฒนาคุณภาพการศึกษา สพฐ.'),
(3, 1, 1, 'welfare', '3. ค่าหนังสือเรียน (โครงการเรียนฟรี 15 ปี)', 650.00, 312, 202800.00, 0, 'จัดสรรตามเกณฑ์ระดับการศึกษา สพฐ.'),
(4, 1, 1, 'welfare', '4. ค่าเครื่องแบบนักเรียน (2 ชุด/คน/ปี)', 380.00, 312, 118560.00, 0, 'อนุบาล 325 บ., ประถม 400 บ.'),
(5, 1, 1, 'welfare', '5. ค่าอุปกรณ์การเรียน (สมุด ดินสอ ยางลบ สี ไม้บรรทัด)', 400.00, 312, 124800.00, 0, 'อนุบาล 290 บ./ปี, ประถม 440 บ./ปี'),
(6, 1, 1, 'activity', '6. ค่ากิจกรรมพัฒนาผู้เรียน (4 กิจกรรมหลัก สพฐ.)', 460.00, 312, 143520.00, 0, 'วิชาการ, คุณธรรม, ทัศนศึกษา, เทคโนโลยี ICT'),
(7, 1, 1, 'welfare', '7. เงินปัจจัยพื้นฐานนักเรียนยากจน (กสศ. / สพฐ.)', 1500.00, 145, 217500.00, 0, 'จำนวนนักเรียนที่ผ่านเกณฑ์คัดกรอง 145 คน'),
(8, 1, 1, 'lunch', '8. ค่าอาหารกลางวัน (อปท. จัดสรรผ่าน อบต./เทศบาล)', 4800.00, 312, 1497600.00, 0, 'อัตรา 24 บ./วัน จำนวน 200 วันทำการ'),
(9, 1, 1, 'fundraising', '9. เงินระดมทรัพยากร / เงินบริจาค / ผ้าป่าเพื่อการศึกษา', 0.00, 1, 185000.00, 1, 'ศิษย์เก่าและคณะกรรมการสถานศึกษาจัดทอดผ้าป่า'),
(10, 1, 1, 'revenue', '10. เงินรายได้สถานศึกษา (ค่าเช่าร้านค้าสหกรณ์, ดอกเบี้ย)', 0.00, 1, 64000.00, 1, 'ดอกเบี้ยเงินฝากธนาคาร และเงินบำรุงสหกรณ์'),
(11, 1, 1, 'other', '11. รายรับอื่น ๆ (เงินอุดหนุนเฉพาะกิจ/โครงการพิเศษ)', 0.00, 1, 50000.00, 1, 'เงินสนับสนุนจาก อบจ. โครงการส่งเสริมดนตรีพื้นบ้าน');
