(1, 1, 1, 'ฝ่ายบริหารงานวิชาการ', 60.00, 1050000.00, 432500.00, 617500.00, '#2563eb', 'พัฒนาหลักสูตร การจัดการเรียนการสอน สื่อ นวัตกรรม และประกันคุณภาพ'),
(2, 1, 1, 'ฝ่ายบริหารงานงบประมาณ', 5.00, 87500.00, 35000.00, 52500.00, '#0284c7', 'การเงิน บัญชี พัสดุ สินทรัพย์ และแผนงานงบประมาณโรงเรียน'),
(3, 1, 1, 'ฝ่ายบริหารงานบุคคล', 12.00, 210000.00, 78000.00, 132000.00, '#059669', 'พัฒนาครู วินัย สวัสดิการ ทัศนศึกษาดูงาน และสรรหาบุคลากร'),
(4, 1, 1, 'ฝ่ายบริหารงานทั่วไป', 8.00, 140000.00, 65400.00, 74600.00, '#d97706', 'อาคารสถานที่ สิ่งแวดล้อม ประชาสัมพันธ์ และชุมชนสัมพันธ์'),
(5, 1, 1, 'งบกลาง / สำรองจ่ายฉุกเฉิน', 15.00, 262500.00, 42000.00, 220500.00, '#7c3aed', 'กรณีภัยพิบัติ ซ่อมแซมฉุกเฉิน และกิจกรรมที่มิได้คาดหมายล่วงหน้า');
INSERT INTO `learner_activities` (`id`, `school_id`, `fiscal_year_id`, `activity_name`, `percentage`, `allocated_amount`, `spent_amount`, `remaining_amount`, `note`) VALUES
(1, 1, 1, '1. กิจกรรมวิชาการ (ค่ายภาษาไทย, คณิตศาสตร์, วิทยาศาสตร์, ภาษาอังกฤษ)', 35.00, 50232.00, 22000.00, 28232.00, 'สพฐ. กำหนดให้เน้นทักษะการคิดและการสื่อสาร'),
(2, 1, 1, '2. กิจกรรมคุณธรรม จริยธรรม ลูกเสือ เนตรนารี และค่ายคุณธรรม', 25.00, 35880.00, 18500.00, 17380.00, 'ค่ายพุทธบุตร และการอยู่ค่ายพักแรมลูกเสือ'),
(3, 1, 1, '3. กิจกรรมทัศนศึกษา แหล่งเรียนรู้นอกสถานที่', 20.00, 28704.00, 0.00, 28704.00, 'ศึกษาแหล่งเรียนรู้พิพิธภัณฑ์วิทยาศาสตร์และประวัติศาสตร์'),
(4, 1, 1, '4. การให้บริการเทคโนโลยีสารสนเทศและการสื่อสาร (ICT/Coding)', 15.00, 21528.00, 12400.00, 9128.00, 'อินเทอร์เน็ตเพื่อการศึกษา ห้องคอมพิวเตอร์ และอุปกรณ์ Coding'),
(5, 1, 1, '5. กิจกรรมอื่น ๆ เพื่อการพัฒนาผู้เรียนตามเอกลักษณ์โรงเรียน', 5.00, 7176.00, 3000.00, 4176.00, 'ส่งเสริมวงดนตรีโปงลางและนาฏศิลป์อีสาน');
INSERT INTO `strategies` (`id`, `school_id`, `fiscal_year_id`, `code`, `name`, `description`) VALUES
(1, 1, 1, 'ยุทธศาสตร์ที่ 1', 'พัฒนาคุณภาพผู้เรียนตามมาตรฐานการศึกษาขั้นพื้นฐานและศตวรรษที่ 21', 'ยกระดับผลสัมฤทธิ์ทางการเรียน RT, NT, O-NET และสมรรถนะผู้เรียน'),
(2, 1, 1, 'ยุทธศาสตร์ที่ 2', 'ส่งเสริมคุณธรรม จริยธรรม วิถีประชาธิปไตย และค่านิยมไทย', 'สร้างจิตสำนึกความเป็นไทย ความรับผิดชอบต่อส่วนรวม และรักษ์สิ่งแวดล้อม'),
(3, 1, 1, 'ยุทธศาสตร์ที่ 3', 'พัฒนาครูและบุคลากรทางการศึกษาสู่ความเป็นครูมืออาชีพ', 'ส่งเสริมการจัดการเรียนรู้ Active Learning และนวัตกรรมดิจิทัล'),
(4, 1, 1, 'ยุทธศาสตร์ที่ 4', 'พัฒนาระบบบริหารจัดการด้วยเทคโนโลยีและการมีส่วนร่วมของทุกภาคส่วน', 'พัฒนาสภาพแวดล้อม อาคารสถานที่ สื่อเทคโนโลยี และประสานชุมชน');
INSERT INTO `goals` (`id`, `strategy_id`, `code`, `name`) VALUES
(1, 1, 'เป้าประสงค์ 1.1', 'ผู้เรียนร้อยละ 80 มีผลการประเมินการอ่านออกเขียนได้ (RT) ในระดับดีขึ้นไป'),
(2, 1, 'เป้าประสงค์ 1.2', 'ผู้เรียนมีทักษะด้านเทคโนโลยีดิจิทัลและการคิดคำนวณตามเกณฑ์'),
(3, 2, 'เป้าประสงค์ 2.1', 'ผู้เรียนทุกคนเข้าร่วมกิจกรรมส่งเสริมคุณธรรม จริยธรรมและค่านิยมที่ดี'),
(4, 3, 'เป้าประสงค์ 3.1', 'ครูร้อยละ 100 ได้รับการอบรมพัฒนาความรู้และจัดทำแผนการสอน Active Learning'),
(5, 4, 'เป้าประสงค์ 4.1', 'สถานศึกษามีสภาพแวดล้อมที่เอื้อต่อการเรียนรู้ ปลอดภัย และมีเทคโนโลยีทันสมัย');
INSERT INTO `indicators` (`id`, `goal_id`, `code`, `name`, `target_value`, `unit`) VALUES
(1, 1, 'ตัวชี้วัด 1.1.1', 'ร้อยละของนักเรียนชั้น ป.1 ที่ผ่านการประเมิน RT ระดับดีขึ้นไป', '85', 'ร้อยละ'),
(2, 2, 'ตัวชี้วัด 1.2.1', 'ร้อยละของนักเรียนชั้น ป.4-6 ที่ผ่านเกณฑ์ทักษะการเขียนโปรแกรมเบื้องต้น', '80', 'ร้อยละ'),
(3, 3, 'ตัวชี้วัด 2.1.1', 'ร้อยละของนักเรียนมีคุณลักษณะอันพึงประสงค์ระดับดีเยี่ยม', '90', 'ร้อยละ'),
(4, 4, 'ตัวชี้วัด 3.1.1', 'จำนวนชั่วโมงเฉลี่ยที่ครูเข้าร่วมการพัฒนาวิชาชีพ (PLC/อบรม)', '25', 'ชั่วโมง/ปี'),
(5, 5, 'ตัวชี้วัด 4.1.1', 'ระดับความพึงพอใจของชุมชนและผู้ปกครองต่อสภาพแวดล้อมโรงเรียน', '92', 'ร้อยละ');
INSERT INTO `projects` (`id`, `school_id`, `fiscal_year_id`, `strategy_id`, `goal_id`, `indicator_id`, `project_code`, `project_name`, `rationale`, `objectives`, `quantitative_goals`, `qualitative_goals`, `kpis`, `procedures`, `duration_start`, `duration_end`, `location`, `target_group`, `responsible_person`, `responsible_id`, `department`, `budget_source`, `allocated_budget`, `spent_budget`, `remaining_budget`, `status`, `approval_status`, `sort_order`) VALUES
(1, 1, 1, 1, 1, 1, 'PROJ-68-01', 'โครงการยกระดับผลสัมฤทธิ์ทางการเรียนและการอ่านออกเขียนได้ (RT, NT, O-NET)', 'เพื่อพัฒนาทักษะการอ่าน การเขียน และการคิดคำนวณของผู้เรียนชั้นประถมศึกษาให้สอดคล้องตามเกณฑ์มาตรฐาน สพฐ.', '1. เพื่อให้นักเรียนชั้น ป.1 อ่านออกเขียนได้ 100%\n2. เพื่อยกระดับคะแนนสอบเฉลี่ย NT และ O-NET สูงกว่าระดับประเทศ', 'นักเรียนชั้น ป.1-6 จำนวน 226 คน', 'นักเรียนมีความสามารถในการอ่าน เขียน และคิดวิเคราะห์ในระดับดีขึ้นไป', 'ร้อยละ 85 ของนักเรียนมีผลสัมฤทธิ์สูงขึ้น', '1. ประเมินความพร้อมต้นปี\n2. จัดค่ายติวเข้มและแบบฝึกทักษะ\n3. จัดสอบจำลองและประเมินผล', '2024-11-01', '2025-03-31', 'ห้องเรียนและอาคารอเนกประสงค์ โรงเรียนเด็กเรียนดี', 'นักเรียนชั้น ป.1 - ป.6 ทุกคน', 'นางสาวกนกพร ใจมั่น', 3, 'ฝ่ายบริหารงานวิชาการ', 'เงินอุดหนุนรายหัว (ฝ่ายวิชาการ)', 45000.00, 28500.00, 16500.00, 'in_progress', 'approved', 1),
(2, 1, 1, 1, 2, 2, 'PROJ-68-02', 'โครงการพัฒนาห้องปฏิบัติการคอมพิวเตอร์และการเรียนรู้โค้ดดิ้ง (Coding for Kids)', 'เพื่อเสริมสร้างทักษะดิจิทัลและกระบวนการคิดเชิงคำนวณให้นักเรียนมีความพร้อมสำหรับโลกยุคใหม่', '1. ปรับปรุงระบบเครือข่ายและเครื่องคอมพิวเตอร์\n2. จัดกิจกรรมการเรียนรู้แบบ Unplugged & Plugged Coding', 'นักเรียนชั้น ป.1-6 และครูผู้สอนคอมพิวเตอร์', 'นักเรียนสามารถเขียนโค้ดและแก้ปัญหาด้วยเหตุผลเชิงตรรกะได้', 'ร้อยละ 80 ของนักเรียนสามารถสร้างผลงานเกม/โปรแกรมขนาดเล็กด้วย Scratch ได้', '1. สำรวจอุปกรณ์\n2. จัดซื้อชุดบอร์ดไมโครบิตและอุปกรณ์เสริม\n3. จัดอบรมเชิงปฏิบัติการ', '2024-12-01', '2025-06-30', 'ห้องปฏิบัติการคอมพิวเตอร์ 1', 'นักเรียนชั้น ป.4 - ป.6', 'นายธีระพล อินทร์ทอง', 3, 'ฝ่ายบริหารงานวิชาการ', 'กิจกรรมพัฒนาผู้เรียน (ICT) + เงินรายได้สถานศึกษา', 60000.00, 48900.00, 11100.00, 'in_progress', 'approved', 2),
(3, 1, 1, 2, 3, 3, 'PROJ-68-03', 'โครงการค่ายคุณธรรม นำความรู้ สู่โรงเรียนสุจริต', 'ปลูกฝังความซื่อสัตย์สุจริต มีวินัย อยู่อย่างพอเพียง และมีจิตสาธารณะตามแนวคิดโรงเรียนคุณธรรม สพฐ.', '1. ส่งเสริมคุณธรรม 5 ประการของโรงเรียนสุจริต\n2. จัดค่ายพุทธบุตรและจิตอาสาพัฒนาโรงเรียน', 'นักเรียนทุกคน 312 คน', 'นักเรียนมีพฤติกรรมเชิงบวกและปฏิบัติตนตามระเบียบวินัย', 'นักเรียนร้อยละ 95 ผ่านเกณฑ์การประเมินคุณลักษณะอันพึงประสงค์', '1. ประชุมวางแผน\n2. จัดค่ายคุณธรรม 2 วัน 1 คืน\n3. กิจกรรมโครงงานคุณธรรมประจำห้อง', '2024-11-15', '2025-02-28', 'วัดสว่างอารมณ์ และหอประชุมโรงเรียน', 'นักเรียน อ.1 - ป.6', 'นางวิไลพร สุขเกษม', 3, 'ฝ่ายบริหารงานบุคคล', 'กิจกรรมพัฒนาผู้เรียน (คุณธรรม)', 35000.00, 35000.00, 0.00, 'completed', 'approved', 3),
(4, 1, 1, 3, 4, 4, 'PROJ-68-04', 'โครงการพัฒนาศักยภาพครูและบุคลากรทางการศึกษาด้านการจัดการเรียนรู้เชิงรุก (Active Learning)', 'เพื่อพัฒนาครูให้สามารถออกแบบหน่วยการเรียนรู้เชิงรุก ผลิตสื่อดิจิทัล และสร้างชุมชนแห่งการเรียนรู้ทางวิชาชีพ (PLC)', '1. ครูทุกคนสามารถจัดทำแผน Active Learning ได้\n2. เกิดนวัตกรรมและผลงานวิจัยในชั้นเรียนอย่างน้อย 1 ชิ้นต่อคน', 'ครูและบุคลากร 22 คน', 'ครูมีความเชี่ยวชาญในการวัดและประเมินผลตามสภาพจริง', 'ครูร้อยละ 100 มีแผนการสอน Active Learning ครบทุกกลุ่มสาระ', '1. จัดอบรมเชิงปฏิบัติการ 3 วัน\n2. นิเทศติดตามการสอน\n3. จัดนิทรรศการแลกเปลี่ยนเรียนรู้ Best Practice', '2024-10-15', '2025-08-31', 'ห้องประชุมเพชรการเรียนรู้', 'คณะครูและบุคลากรทางการศึกษา', 'ดร.สมศักดิ์ พัฒนศึกษา', 2, 'ฝ่ายบริหารงานบุคคล', 'งบจัดสรรฝ่ายบริหารงานบุคคล', 40000.00, 22000.00, 18000.00, 'in_progress', 'approved', 4),
(5, 1, 1, 4, 5, 5, 'PROJ-68-05', 'โครงการปรับปรุงภูมิทัศน์และสภาพแวดล้อมเพื่อความปลอดภัยในสถานศึกษา (Safe School)', 'จัดเตรียมสภาพแวดล้อม สนามเด็กเล่น ห้องน้ำ และระบบไฟฟ้าให้ปลอดภัยถูกสุขลักษณะตามนโยบายโรงเรียนปลอดภัย สพฐ.', '1. ซ่อมบำรุงเครื่องเล่นสนามเด็กเล่นอนุบาล\n2. ทาสีทางม้าลายและป้ายจราจรภายในโรงเรียน\n3. ติดตั้งกล้องวงจรปิดเพิ่มเติม 4 จุด', 'พื้นที่บริเวณโรงเรียน 15 ไร่ และอาคารเรียน 3 หลัง', 'โรงเรียนมีความสะอาด ร่มรื่น และปลอดภัย ปราศจากอุบัติเหตุ', 'อัตราการเกิดอุบัติเหตุในโรงเรียนลดลงเป็นศูนย์', '1. สำรวจจุดเสี่ยง\n2. จัดซื้อวัสดุอุปกรณ์\n3. ดำเนินการปรับปรุงซ่อมแซม', '2024-10-01', '2025-05-31', 'บริเวณโรงเรียนเด็กเรียนดี', 'นักเรียน ครู และผู้ปกครอง', 'นายประเสริฐ ช่างทอง', 1, 'ฝ่ายบริหารงานทั่วไป', 'งบจัดสรรฝ่ายบริหารงานทั่วไป + เงินผ้าป่าการศึกษา', 55000.00, 34500.00, 20500.00, 'in_progress', 'approved', 5),
(6, 1, 1, 1, 1, 1, 'PROJ-68-06', 'โครงการทัศนศึกษาเปิดโลกการเรียนรู้ แหล่งเรียนรู้ทางวิทยาศาสตร์และประวัติศาสตร์', 'เสริมสร้างประสบการณ์ตรงนอกห้องเรียน กระตุ้นความใฝ่รู้และจิตสำนึกรักท้องถิ่น', '1. พานักเรียนไปศึกษาแหล่งเรียนรู้พิพิธภัณฑ์ธรรมชาติวิทยาและศูนย์วิทยาศาสตร์\n2. จัดทำสมุดบันทึกการเรียนรู้', 'นักเรียนชั้น ป.4-6 จำนวน 112 คน', 'นักเรียนได้เรียนรู้ผ่านประสบการณ์จริงและทำงานร่วมกันเป็นทีม', 'ร้อยละ 100 ของนักเรียนที่เข้าร่วมส่งสมุดบันทึกการเรียนรู้', '1. สำรวจสถานที่และติดต่อรถโดยสาร\n2. ทำหนังสือขออนุญาตผู้ปกครอง\n3. จัดการเดินทางและสรุปผล', '2025-01-10', '2025-02-15', 'ศูนย์วิทยาศาสตร์เพื่อการศึกษา และพิพิธภัณฑ์ไดโนเสาร์ภูเวียง', 'นักเรียนชั้น ป.4 - ป.6', 'นางสาวกนกพร ใจมั่น', 3, 'ฝ่ายบริหารงานวิชาการ', 'กิจกรรมพัฒนาผู้เรียน (ทัศนศึกษา)', 28000.00, 0.00, 28000.00, 'not_started', 'approved', 6),
(7, 1, 1, 4, 5, 5, 'PROJ-68-07', 'โครงการพัฒนาระบบข้อมูลสารสนเทศและแผนงานงบประมาณโรงเรียน', 'เพื่อพัฒนาระบบฐานข้อมูล จัดสรรงบประมาณ และติดตามการใช้จ่ายให้โปร่งใส ตรวจสอบได้ตามระเบียบพัสดุภาครัฐ', '1. จัดทำระบบแผนปฏิบัติการดิจิทัล\n2. จัดทำรายงานงบประมาณรายไตรมาส', 'รายงานแผนปฏิบัติการและสรุปงบประมาณประจำปี 1 เล่ม พร้อมระบบออนไลน์', 'ระบบบริหารงบประมาณมีความถูกต้อง แม่นยำ และโปร่งใส', 'การเบิกจ่ายงบประมาณเป็นไปตามแผนร้อยละ 95 ขึ้นไป', '1. รวบรวมข้อมูลแผนงาน\n2. อบรมผู้รับผิดชอบโครงการในการคีย์ข้อมูล\n3. จัดทำรูปเล่มรายงานส่ง สพป.', '2024-10-01', '2025-09-30', 'ห้องสำนักงานแผนงานและงบประมาณ', 'คณะกรรมการบริหารโรงเรียนและหัวหน้าโครงการ', 'นายพิเชษฐ์ ปัญญาวงศ์', 1, 'ฝ่ายบริหารงานงบประมาณ', 'งบจัดสรรฝ่ายบริหารงานงบประมาณ', 25000.00, 15000.00, 10000.00, 'in_progress', 'approved', 7),
(8, 1, 1, 2, 3, 3, 'PROJ-68-08', 'โครงการส่งเสริมสุขภาพ กีฬา และสุขาภิบาลอาหารกลางวันนักเรียน', 'เพื่อให้นักเรียนได้รับสารอาหารครบถ้วน มีสมรรถภาพทางกายที่แข็งแรง และมีสุขนิสัยที่ดี', '1. จัดซื้ออุปกรณ์กีฬาพื้นฐาน\n2. ตรวจสอบสารปนเปื้อนในอาหาร\n3. จัดกิจกรรมแข่งขันกีฬาสีสัมพันธ์ภายใน', 'นักเรียนทุกคน 312 คน', 'นักเรียนมีน้ำหนักส่วนสูงตามเกณฑ์มาตรฐานกรมอนามัย', 'นักเรียนร้อยละ 90 มีสมรรถภาพทางกายผ่านเกณฑ์', '1. ชั่งน้ำหนักวัดส่วนสูงทุกเดือน\n2. จัดการแข่งขันกีฬาสี\n3. ให้ความรู้โภชนาการ', '2024-11-01', '2025-07-31', 'สนามฟุตบอลและโรงอาหารโรงเรียน', 'นักเรียนทุกระดับชั้น', 'นายอนุรักษ์ ยิ้มแย้ม', 3, 'ฝ่ายบริหารงานทั่วไป', 'งบกลาง / งบสนับสนุน อปท.', 32000.00, 18000.00, 14000.00, 'in_progress', 'approved', 8);
