INSERT INTO `budget_transactions` (`id`, `school_id`, `fiscal_year_id`, `project_id`, `doc_number`, `transaction_date`, `item_description`, `amount`, `payee`, `receipt_number`, `approved_by`, `status`) VALUES
(1, 1, 1, 1, 'บก.68/001', '2024-11-12', 'เบิกจ่ายค่าแบบฝึกเสริมทักษะภาษาไทยและการอ่าน ป.1-6', 18080.00, 'ร้านศึกษาภัณฑ์พาณิชย์', 'REC-2411-098', 'ดร.สมศักดิ์ พัฒนศึกษา (ผู้อำนวยการ)', 'approved'),
(2, 1, 1, 1, 'บก.68/002', '2024-11-25', 'เบิกจ่ายค่ากระดาษ A4 และค่าอาหารว่างติวเข้ม RT', 6600.00, 'หจก. ศิลาเครื่องเขียน', 'INV-77312', 'ดร.สมศักดิ์ พัฒนศึกษา (ผู้อำนวยการ)', 'approved'),
